attempts.code:
# notes/*.txt 의 NEEDLE 일치 줄을 전수 수집 — 파일·줄번호·내용 그대로 보존
# (주변 본문을 따로 읽지 않고, 상위 N 추리기 등 행 감축도 하지 않는다)
$히트 = [self:grep]{pattern: "NEEDLE", root_path: "notes", file_pattern: "*.txt", output_mode: "content", regex: false, limit: 100000, include_logs: true}

# 원장 사본 저장(부수 효과) — 반환값은 아래에서 히트 자체로 낸다
$저장 = $히트 >> [self:write]{path: "outputs/needle_hits.json", format: "json"}

# 프로그램의 최종 결과 = 일치 위치 전부(파일·줄번호·내용 3열 그대로)
$히트 >> [table:select]{columns: ["파일", "줄번호", "내용"]}

