# 1) drafts/*.md 중 수정시각이 가장 최근인 문서 한 건
$docs = [self:file_find]{path: "drafts", pattern: "*.md"} >> [table:sort]{by: "mtime", desc: true} >> [table:take]{n: 1}
$path = "${docs.items.0.path}"
$doc = [self:read]{path: "$path", start_line: 11, end_line: 22}
[if: exists($doc.content)]{[self:write]{path: "outputs/excerpt.txt", content: "${doc.content}"}}
[else]{[self:write]{path: "outputs/excerpt.txt", content: "${doc.text?}"}}

# 2) queue.json: state=open & priority>=3, id 오름차순, 모든 필드 보존
$rows = [self:ledger]{op: "select", path: "queue.json"} ?? [self:read]{path: "queue.json"}
$open = $rows >> [table:filter]{where: {field: "state", op: "eq", value: "open"}} >> [table:filter]{where: {field: "priority", op: "gte", value: 3}}
$open >> [table:sort]{by: "id"} >> [self:write]{path: "outputs/pending.json", format: "json"}

