# 자료 반입 정리 — 승인분 아카이브 누적 + 반려분 별도 보관
[self:mkdir]{path: "outputs"}

$제출 = [self:read]{path: "submissions.json"}
$기존 = [self:read]{path: "existing.json"}

# 승인된 행만 id·kind·value 로 좁힌다 (원래 제출 순서 유지)
$승인 = $제출 >> [table:filter]{where: "approved == true"} >> [table:select]{columns: ["id", "kind", "value"]}

# 기존 행 먼저, 새 고유 행은 뒤에 — id+kind 복합키가 같으면 기존 행 전체 보존
[fn:원장에누적]{옛것: "$기존", 새것: "$승인", 키: ["id", "kind"], 원장: "outputs/archive.json"}

# 반려분은 원래 행 그대로 따로 보관 (입력 파일은 무변경)
$제출 >> [table:filter]{where: "approved == false"} >> [self:write]{path: "outputs/rejected.json", format: "json"}

# 자료 반입 정리 — 입력 파일은 읽기만 한다
# 1) 입력 읽기 (배열/items 봉투 모두 대응)
$sub = [self:ledger]{op: "select", path: "submissions.json"} ?? [self:read]{path: "submissions.json"}
$exist = [self:ledger]{op: "select", path: "existing.json"} ?? [self:read]{path: "existing.json"}

# 2) 승인 행: id·kind·value 만 (제출 순서 보존) / 미승인 행: 원래 행 전체
$approved = $sub >> [table:filter]{where: {field: "approved", op: "eq", value: true}} >> [table:select]{columns: ["id", "kind", "value"]}
$rejected = $sub >> [table:filter]{where: {field: "approved", op: "eq", value: false}}

# 3) 미승인 원래 행 별도 보관
$rejected >> [self:write]{path: "outputs/rejected.json", format: "json"}

# 4) (id, kind) 복합키 — 기존에 이미 있는 조합은 제외, 승인분 내부 중복도 첫 행만
$ekeys = $exist >> [table:compute]{set: {dk: "id + '|' + kind"}}
$new = $approved >> [table:compute]{set: {dk: "id + '|' + kind"}} >> [table:dedup]{by: "dk"} >> [table:filter]{where: {field: "dk", op: "not_in", value: "${ekeys.items.*.dk}"}} >> [table:select]{columns: ["id", "kind", "value"]}

# 5) 기존 행 전체 보존 후 새 고유 행을 제출 순서대로 뒤에 append
$exist & $new >> [table:union] >> [self:write]{path: "outputs/archive.json", format: "json"}

# 자료 반입 정리 — 승인분 아카이브 + 반려분 별도 보관 (입력 파일 무변경)
[self:mkdir]{path: "outputs"}

$제출 = [self:read]{path: "submissions.json"}
$기존 = [self:read]{path: "existing.json"}

# 승인분: approved=true 행에서 id·kind·value 만 (제출 원래 순서 유지)
$승인 = $제출 >> [table:filter]{where: {field: "approved", op: "eq", value: true}} >> [table:select]{columns: ["id", "kind", "value"]}

# 기존 행 먼저 + 승인분 뒤에, (id, kind) 복합키 중복 시 기존 행 전체 보존
[fn:원장에누적]{옛것: "$기존", 새것: "$승인", 키: ["id", "kind"], 원장: "outputs/archive.json"}

# 반려분: approved=false 인 원래 행 전체를 그대로 보관
$거절 = $제출 >> [table:filter]{where: {field: "approved", op: "eq", value: false}}
$거절 >> [self:write]{path: "outputs/rejected.json", format: "json"}

# 확인
[self:read]{path: "outputs/archive.json"} >> [table:take]{n: 8}

# 자료 반입 정리 — 승인분 아카이브 + 반려분 별도 보관 (입력 파일 무변경)

$제출 = [self:read]{path: "submissions.json"}
$기존 = [self:read]{path: "existing.json"}

# 승인분: approved=true 행에서 id·kind·value 만 (제출 원래 순서 유지)
$승인 = $제출 >> [table:filter]{where: {field: "approved", op: "eq", value: true}} >> [table:select]{columns: ["id", "kind", "value"]}

# 기존 행 먼저 + 승인분 뒤에, (id, kind) 복합키 중복 시 기존 행 전체 보존
[fn:원장에누적]{옛것: "$기존", 새것: "$승인", 키: ["id", "kind"], 원장: "outputs/archive.json"}

# 반려분: approved=false 인 원래 행 전체를 그대로 보관
$거절 = $제출 >> [table:filter]{where: {field: "approved", op: "eq", value: false}}
$거절 >> [self:write]{path: "outputs/rejected.json", format: "json"}

# 확인
[self:read]{path: "outputs/archive.json"} >> [table:take]{n: 8}

# 자료 반입 정리: 승인 행 반입 + 기존 행 보존 + 반려 행 별도 보관

$sub = [self:read]{path: "submissions.json"}
$exist = [self:read]{path: "existing.json"}

# 승인된 제출에서 id·kind·value 만 (제출 순서 유지)
$approved = $sub >> [table:filter]{where: "approved == true"} >> [table:select]{columns: ["id", "kind", "value"]}

# 기존 행이 앞 → 승인 신규가 뒤, (id, kind) 중복은 앞(기존 행 전체) 보존
$exist & $approved >> [table:union] >> [table:dedup]{by: ["id", "kind"]} >> [self:write]{path: "outputs/archive.json", format: "json"}

# 반려 행은 원래 행 그대로 별도 보관
$sub >> [table:filter]{where: "approved == false"} >> [self:write]{path: "outputs/rejected.json", format: "json"}

[self:mkdir]{path: "outputs"}
$기존 = [self:read]{path: "existing.json"}
$제출 = [self:read]{path: "submissions.json"}
$승인 = $제출 >> [table:filter]{where: {field: "approved", op: "eq", value: true}} >> [table:select]{columns: ["id", "kind", "value"]}
[fn:원장에누적]{옛것: "$기존", 새것: "$승인", 키: ["id", "kind"], 원장: "outputs/archive.json"}
$거절 = $제출 >> [table:filter]{where: {field: "approved", op: "eq", value: false}}
$거절 >> [self:write]{path: "outputs/rejected.json", format: "json"}

$기존 = [self:read]{path: "existing.json"}
$제출 = [self:read]{path: "submissions.json"}
$승인 = $제출 >> [table:filter]{where: {field: "approved", op: "eq", value: true}} >> [table:select]{columns: ["id", "kind", "value"]}
[fn:원장에누적]{옛것: "$기존", 새것: "$승인", 키: ["id", "kind"], 원장: "outputs/archive.json"}
$거절 = $제출 >> [table:filter]{where: {field: "approved", op: "eq", value: false}}
$거절 >> [self:write]{path: "outputs/rejected.json", format: "json"}

# 자료 반입 정리 — submissions.json + existing.json → outputs/archive.json, outputs/rejected.json
$sub = [self:read]{path: "submissions.json"} ?? [self:ledger]{op: "select", path: "submissions.json"}
$ex = [self:read]{path: "existing.json"} ?? [self:ledger]{op: "select", path: "existing.json"}

# 1) 반려분: approved=false 인 원래 행 전체를 그대로 보관
$sub >> [table:filter]{where: {field: "approved", op: "eq", value: false}} >> [self:write]{path: "outputs/rejected.json", format: "json"}

# 2) 기존 행의 (id, kind) 복합키 목록
$exkeys = $ex >> [table:each]{limit: 2000} {
  $return = [{k: "${it.id}|${it.kind}"}]
}

# 3) 승인분에서 id·kind·value 만 취하고 복합키 부여 (제출 순서 유지)
$appr = $sub >> [table:filter]{where: {field: "approved", op: "eq", value: true}} >> [table:each]{limit: 2000} {
  $return = [{id: $it.id, kind: $it.kind, value: $it.value, _k: "${it.id}|${it.kind}"}]
}

# 4) 기존과 겹치는 (id,kind) 는 제외(기존 행 보존), 제출분 내 중복은 첫 행만
$uniq = $appr >> [table:filter]{where: {field: "_k", op: "not_in", value: "${exkeys.items.*.k}"}} >> [table:dedup]{by: "_k"} >> [table:select]{columns: ["id", "kind", "value"]}

# 5) 기존 행 먼저, 새 고유 행은 원래 제출 순서로 뒤에
$ex & $uniq >> [table:union] >> [self:write]{path: "outputs/archive.json", format: "json"}
